## Паттерн Классификации через ИИ
```python
from openai import OpenAI

def classify_email(subject: str, body: str) -> str:
    client = OpenAI()
    response = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=[{
            'role': 'user',
            'content': f"""Классифицируй это письмо в одну из категорий: [invoice, support_request, sales_lead, job_application, other]

Тема: {subject}
Тело письма: {body[:500]}

Верни ТОЛЬКО название категории (label)."""
        }]
    )
    return response.choices[0].message.content.strip()
```

## Извлечение данных: Regex + AI
```python
import re

def extract_invoice_data(email_body: str) -> dict:
    # Сначала пробуем регулярки (быстро и дешево)
    amount_match = re.search(r'\$([\d,]+\.?\d*)', email_body)
    invoice_match = re.search(r'Invoice #?(\w+)', email_body, re.I)

    if amount_match and invoice_match:
        return {'amount': float(amount_match.group(1).replace(',', '')),
                'invoice_number': invoice_match.group(1)}

    # Если данные не структурированы — используем ИИ
    return ai_extract(email_body)
```

